//! 📮️ Native original port lease, atomic final queue and fixed-grant custody laws.
use super::*;
use crate::RequestId;

#[test]
fn original_tool_run_port_preserves_atomic_final_queue_and_full_grants(){
    let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let grant:RetainedCloneGrant=serde_json::from_value(law["grant"].clone()).unwrap();
    for reserve in[0,1,17]{let(mut source,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let port=ToolRunJobPort::default();port.inner.effects.lock().unwrap().reserve(reserve);Some(port)});let mut born=heap.requested_bytes;let mut released=heap.released_bytes;let pointer=Arc::as_ptr(&source.as_ref().unwrap().inner);let quote=source.as_ref().unwrap().original_close_demands().unwrap();for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ToolRunJobPort::admit_original_close(&mut source,denied));assert!(result.unwrap().is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(Arc::as_ptr(&source.as_ref().unwrap().inner),pointer);}
        let((mut owner,progress),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ToolRunJobPort::admit_original_close(&mut source,grant).unwrap().unwrap());assert!(source.is_none());assert!(progress.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(Arc::as_ptr(&owner.source.as_ref().unwrap().inner),pointer);let mut turns=0;while !owner.terminal_is_empty(){let(demand,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.demands().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut denied=vec![RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}];if demand.release_bytes>0{denied.push(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant});}for grant in denied{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;turns+=1;assert!(turns<100000);}assert_eq!(born,released);let((),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));println!("[DEBUG] original port reserve={reserve} turns={turns} pointerSame physical={released} unchanged5currencies terminalDrop0");
    }
    let port=ToolRunJobPort::default();let weak=Arc::downgrade(&port.inner);assert!(port.original_close_demands().is_err());drop(weak);port.dispatch(Effect::DispatchAction{req:RequestId(3),action:"original".into(),args:None,delay_ms:0});assert!(port.original_close_demands().is_err());let alias=port.clone();let mut source=Some(port);let(mut owner,_)=ToolRunJobPort::admit_original_close(&mut source,grant).unwrap().unwrap();drop(alias);let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,step.progress().released_bytes));assert!(!owner.terminal_is_empty());let effects=owner.effects.as_ref().unwrap();assert_eq!(effects.len(),1);let pointer=effects.as_slices().0.as_ptr();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(owner.effects.as_ref().unwrap().as_slices().0.as_ptr(),pointer);let _retained_original=std::mem::ManuallyDrop::new(owner);println!("[DEBUG] original alias became sole after admission: final queued effect retained Unsupported with native pointer; no false Complete");
}
